import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIODeviceError, GPIODeviceClosed

PINS = [2, 3, 4]
INTERVAL_SECONDS = 60

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                devices.append(dev)
                print(f"GPIO {pin} initialized as output.")
            except GPIODeviceError as exc:
                print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                return 1

        while _running:
            for dev in devices:
                try:
                    state = dev.value
                except GPIODeviceClosed:
                    print("Error: device closed unexpectedly.", file=sys.stderr)
                    return 1
                print(f"GPIO {dev.pin.number} -> {state}")

            for _ in range(INTERVAL_SECONDS):
                if not _running:
                    break
                time.sleep(1)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

