import signal
import sys
import time

from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas


class DisplayController:
    """Manage an SSD1306 OLED display and show sensor readings."""

    def __init__(self, port: str = "1", address: int = 0x3C):
        self.port = port
        self.address = address
        self.device = None
        self._running = True

    def initialize(self) -> bool:
        """Open the I2C bus and configure the SSD1306. Return True on success."""
        try:
            serial = i2c(port=self.port, address=self.address)
            self.device = ssd1306(serial)
            return True
        except Exception as exc:
            print(f"Error initializing SSD1306 on port {self.port} "
                  f"address 0x{self.address:02X}: {exc}", file=sys.stderr)
            self.device = None
            return False

    def show_reading(self, reading: str) -> None:
        """Render a single reading on the OLED display."""
        if self.device is None:
            return
        try:
            with canvas(self.device) as draw:
                draw.text((0, 0), reading, fill="white")
        except Exception as exc:
            print(f"Error displaying reading: {exc}", file=sys.stderr)

    def stop(self) -> None:
        """Signal the main loop to exit and release the display."""
        self._running = False

    def cleanup(self) -> None:
        """Release the display device."""
        if self.device is not None:
            try:
                self.device.cleanup()
            except Exception:
                pass
            self.device = None


def read_sensor_data() -> str:
    """Return a simulated sensor reading for demonstration."""
    return "Sensor: 23.4 C"


def validate_reading(reading: str) -> bool:
    """Validate that the reading is not empty and contains a digit."""
    return bool(reading) and any(c.isdigit() for c in reading)


def main() -> int:
    controller = DisplayController(port="1", address=0x3C)

    if not controller.initialize():
        controller.cleanup()
        return 1

    def _signal_handler(signum, frame):
        controller.stop()

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        while controller._running:
            reading = read_sensor_data()
            if not validate_reading(reading):
                print("Invalid reading received, skipping display.",
                      file=sys.stderr)
            else:
                controller.show_reading(reading)
            time.sleep(2)
    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
        return 1
    finally:
        controller.cleanup()

    return 0


if __name__ == "__main__":
    sys.exit(main())

