import signal
import sys
import time

PORT = "/dev/serial0"
BAUD = 9600
TIMEOUT = 1.0
INTERVAL = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUD,
            timeout=TIMEOUT,
            write_timeout=TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)
    except OSError as exc:
        print(f"Error: device unavailable {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    print(f"Connected to {PORT} @ {BAUD} baud. Press Ctrl+C to stop.")

    try:
        while _running:
            try:
                raw = ser.readline()
                if not raw:
                    print("Warning: no response within timeout (device may be absent).")
                else:
                    text = raw.decode("utf-8", errors="replace").strip()
                    if text:
                        print(text)
            except serial.SerialException as exc:
                print(f"Error: serial read failed: {exc}", file=sys.stderr)
                break
            except OSError as exc:
                print(f"Error: I/O failure: {exc}", file=sys.stderr)
                break

            time.sleep(INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Serial port closed. Exiting.")

if __name__ == "__main__":
    main()

