import signal
import sys
import time

try:
    from picamera2 import Picamera2
except ImportError:
    print("Error: picamera2 library not installed. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)


class CameraCapture:
    """
    A class to encapsulate camera capture functionality using picamera2.
    """

    def __init__(self, timeout=5.0):
        self.timeout = timeout
        self.camera = None
        self._running = True

    def _signal_handler(self, signum, frame):
        print(f"\nReceived signal {signum}, shutting down...", file=sys.stderr)
        self._running = False

    def capture_image(self, filename):
        """
        Captures an image using the Raspberry Pi camera and saves it to a file.

        Args:
            filename (str): The name of the file to save the image to.

        Returns:
            bool: True if the image was captured and saved successfully, False otherwise.
        """
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        try:
            self.camera = Picamera2()
        except Exception as e:
            print(f"Error: Failed to initialize camera: {e}", file=sys.stderr)
            return False

        try:
            self.camera.start()
        except Exception as e:
            print(f"Error: Failed to start camera: {e}", file=sys.stderr)
            return False

        start_time = time.time()
        while self._running and (time.time() - start_time) < self.timeout:
            try:
                self.camera.capture_file(filename)
                print(f"Image captured and saved as '{filename}'")
                return True
            except Exception as e:
                print(f"Error capturing image: {e}", file=sys.stderr)
                time.sleep(0.5)

        print("Error: Timed out waiting for camera response.", file=sys.stderr)
        return False

    def cleanup(self):
        """Releases the camera resource."""
        if self.camera is not None:
            try:
                self.camera.stop()
            except Exception:
                pass
            try:
                self.camera.close()
            except Exception:
                pass
            self.camera = None


def main():
    capture = CameraCapture(timeout=5.0)
    image_file = "my_image.jpg"

    if capture.capture_image(image_file):
        sys.exit(0)
    else:
        sys.exit(1)


if __name__ == "__main__":
    main()

