import signal
import sys
import time

from gpiozero import PWMOutputDevice

PWM_PINS = [12, 20, 21]
PWM_FREQUENCY = 1000.0
UPDATE_INTERVAL = 0.03

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pwms = []
    try:
        for pin in PWM_PINS:
            pwms.append(PWMOutputDevice(pin, frequency=PWM_FREQUENCY, initial_value=0.0))

        while _running:
            for i, pw in enumerate(pwms):
                state = "ON" if pw.value > 0.0 else "OFF"
                print(f"GPIO {PWM_PINS[i]} -> {state}")
                time.sleep(UPDATE_INTERVAL)

    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
    finally:
        for pw in pwms:
            try:
                pw.close()
            except Exception:
                pass
        print("GPIO cleanup done.")


if __name__ == "__main__":
    main()

