import time
import signal
import sys
from picamera2 import Picamera2

running = True

def handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

def capture_and_save_image(camera, filename):
    """Capture an image and save it to the specified file."""
    try:
        camera.capture_file(filename)
        return True
    except Exception as e:
        print(f"Error capturing image: {e}", file=sys.stderr)
        return False

def main():
    camera = None
    try:
        camera = Picamera2()
        camera.start()
        print("Camera started. Capturing images every 60 seconds...")

        while running:
            image_filename = "image.jpg"
            if capture_and_save_image(camera, image_filename):
                print(f"Image saved to {image_filename}")
            else:
                print(f"Failed to capture image: {image_filename}", file=sys.stderr)

            # Sleep in small increments so signals are caught promptly
            for _ in range(60):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if camera is not None:
            try:
                camera.stop()
                camera.close()
            except Exception:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

