import serial
import signal
import sys
import time

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def exchange_data(port: str, baudrate: int, num_readings: int, delay: float) -> None:
    global _running
    _running = True

    try:
        ser = serial.Serial(
            port=port,
            baudrate=baudrate,
            timeout=1.0,
            write_timeout=1.0,
        )
    except serial.SerialException as exc:
        print(f"Error: could not open serial port {port}: {exc}", file=sys.stderr)
        return

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        for i in range(num_readings):
            if not _running:
                print("Interrupted by signal; exiting early.")
                break

            try:
                ser.reset_input_buffer()
                ser.reset_output_buffer()

                if ser.in_waiting > 0:
                    data = ser.read(ser.in_waiting)
                    if data:
                        print(f"Reading {i + 1}/{num_readings}: {data!r}")
                    else:
                        print(f"Reading {i + 1}/{num_readings}: no data received")
                else:
                    print(f"Reading {i + 1}/{num_readings}: no data available (timeout)")

            except serial.SerialException as exc:
                print(f"Error during read on reading {i + 1}: {exc}", file=sys.stderr)
                break

            if i < num_readings - 1 and _running:
                time.sleep(delay)

    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Serial port closed.")

if __name__ == "__main__":
    exchange_data(port="/dev/serial0", baudrate=9600, num_readings=3, delay=1.0)

