import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, BadPinFactory

# HC-SR04 ECHO -> GPIO 14, TRIG -> GPIO 24 (BCM numbering)
ECHO_PIN = 14
TRIGGER_PIN = 24

# HC-SR04 practical range (cm)
MIN_CM = 2.0
MAX_CM = 400.0

# Timeout for a single measurement (seconds)
TIMEOUT_S = 1.0

# Polling interval (seconds)
POLL_INTERVAL_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def measure_distance(sensor):
    """Return distance in cm, or None if the device did not respond."""
    deadline = time.monotonic() + TIMEOUT_S
    while _running:
        try:
            dist = sensor.distance * 100.0  # gpiozero reports meters
            if MIN_CM <= dist <= MAX_CM:
                return round(dist, 2)
        except GPIOZeroError:
            pass
        except Exception:
            pass
        if time.monotonic() >= deadline:
            return None
        time.sleep(0.01)
    return None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = DistanceSensor(echo=ECHO_PIN, trigger=TRIGGER_PIN, max_distance=4.0)
    except BadPinFactory:
        print("ERROR: No GPIO pin factory available.", file=sys.stderr)
        sys.exit(1)
    except GPIOZeroError as exc:
        print(f"ERROR: Failed to initialize HC-SR04 on GPIO {ECHO_PIN}/{TRIGGER_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"ERROR: Unexpected initialization failure: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            dist = measure_distance(sensor)
            if dist is not None:
                print(f"Distance: {dist} cm")
            else:
                print("Distance: -- (no response within timeout)")
            time.sleep(POLL_INTERVAL_S)
    finally:
        try:
            sensor.close()
        except Exception:
            pass
        print("Program terminated.")


if __name__ == "__main__":
    main()

