import serial
import signal
import sys
import time

PORT = "/dev/serial0"
BAUD = 9600
TIMEOUT = 1.0
READ_INTERVAL = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _read_once(ser):
    """Return a valid reading or None if the read failed/is invalid."""
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        text = raw.decode("ascii", errors="replace").strip()
    except Exception as exc:
        print(f"Decode error: {exc}", file=sys.stderr)
        return None
    if not text:
        return None
    try:
        value = float(text)
    except ValueError:
        print(f"Invalid data (not a float): {text!r}", file=sys.stderr)
        return None
    if value < 0 or value > 100:
        print(f"Out of range ({value}): {text!r}", file=sys.stderr)
        return None
    return value

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(PORT, BAUD, timeout=TIMEOUT)
    except serial.SerialException as exc:
        print(f"Failed to open {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            reading = _read_once(ser)
            if reading is not None:
                print(f"Reading: {reading}")
            time.sleep(READ_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

