            if _running and readings_taken < SAMPLE_COUNT:
                time.sleep(SAMPLE_INTERVAL)

        if not _running:
            print("\nInterrupted by signal.")
            return 130

        print(f"Completed {readings_taken} of {SAMPLE_COUNT} readings.")
        return 0

    finally:
        if adc is not None:
            try:
                adc.deinit()
            except Exception:
                pass
        if i2c is not None:
