        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            result = read_measurement(bus)
            if result is None:
                print("Error: invalid reading from PCF8574 at 0x27", file=sys.stderr)
            else:
                print(f"Measurement: {result}")
            time.sleep(READ_INTERVAL_S)
