import signal
import sys
import time

import serial

PORT = "/dev/serial0"
BAUD = 115200
TIMEOUT = 1.0
INTERVAL = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _read_once(ser):
    """Return a valid reading or None on timeout/error."""
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        text = raw.decode("ascii", errors="replace").strip()
    except Exception as exc:
        print(f"Decode error: {exc}", file=sys.stderr)
        return None
    if not text:
        return None
    try:
        value = float(text)
    except ValueError:
        print(f"Invalid data (not a float): '{text}'", file=sys.stderr)
        return None
    if not (-100.0 <= value <= 100.0):
        print(f"Value out of range: {value}", file=sys.stderr)
        return None
    return value


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUD,
            timeout=TIMEOUT,
            write_timeout=TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Failed to open {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    print(f"Connected to {PORT} @ {BAUD} baud. Press Ctrl-C to stop.")

    try:
        while _running:
            reading = _read_once(ser)
            if reading is not None:
                print(f"Reading: {reading:.2f}")
            time.sleep(INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Exited cleanly.")


if __name__ == "__main__":
    main()

