import sys
import time
import signal
import numpy as np
from picamera2 import Picamera2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

signal.signal(signal.SIGINT, _handle_signal)
signal.signal(signal.SIGTERM, _handle_signal)

def capture_image(camera: Picamera2, filename: str) -> bool:
    """Capture a single image and save it to filename. Returns True on success."""
    try:
        camera.capture_file(filename)
        return True
    except Exception as exc:
        print(f"Error capturing image: {exc}", file=sys.stderr)
        return False

def check_image_validity(filename: str) -> bool:
    """Validate the captured image by checking its shape. Returns True if valid."""
    try:
        import cv2
        img = cv2.imread(filename, cv2.IMREAD_GRAYSCALE)
        if img is None:
            print(f"Error: could not read image '{filename}'", file=sys.stderr)
            return False
        if img.size == 0:
            print(f"Error: image '{filename}' is empty", file=sys.stderr)
            return False
        return True
    except Exception as exc:
        print(f"Error checking image '{filename}': {exc}", file=sys.stderr)
        return False

def main() -> int:
    camera = None
    try:
        camera = Picamera2()
        still_config = camera.create_still_configuration()
        camera.configure(still_config)
        camera.start()
        time.sleep(2)  # warm-up

        for cycle in range(2):
            if not _running:
                print("Interrupted by signal; exiting early.", file=sys.stderr)
                break

            timestamp = time.strftime("%Y%m%d%H%M%S")
            filename = f"image_{timestamp}.jpg"

            if capture_image(camera, filename):
                if check_image_validity(filename):
                    print(f"Cycle {cycle + 1}: Image saved and valid -> {filename}")
                else:
                    print(f"Cycle {cycle + 1}: Image saved but invalid -> {filename}", file=sys.stderr)
            else:
                print(f"Cycle {cycle + 1}: Image capture failed", file=sys.stderr)

            if cycle < 1:  # only sleep between cycles, not after the last one
                time.sleep(2)

    except Exception as exc:
        print(f"Fatal error: {exc}", file=sys.stderr)
        return 1
    finally:
        if camera is not None:
            try:
                camera.stop()
            except Exception:
                pass
        print("Program finished.")
    return 0

if __name__ == "__main__":
    sys.exit(main())

