import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIODeviceError, GPIODeviceClosed

# --- Configuration -----------------------------------------------------------
OUTPUT_PINS = [17, 18]          # BCM pin numbers
POLL_INTERVAL = 5               # seconds between updates

# --- Globals for cleanup -----------------------------------------------------
_devices: list[OutputDevice] = []
_running = True


def _cleanup() -> None:
    """Turn off and close every device we opened."""
    for dev in _devices:
        try:
            dev.off()
        except GPIODeviceClosed:
            pass
        except Exception:
            pass
        try:
            dev.close()
        except Exception:
            pass
    _devices.clear()


def _handle_signal(signum, frame) -> None:
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _set_output(pin: int, state: bool) -> bool:
    """Open the pin if needed and drive it to *state*. Returns True on success."""
    try:
        dev = _devices[pin - 1]
    except IndexError:
        try:
            dev = OutputDevice(pin)
            _devices.append(dev)
        except GPIODeviceError as exc:
            print(f"ERROR: cannot open GPIO {pin}: {exc}", file=sys.stderr)
            return False
    except Exception as exc:
        print(f"ERROR: unexpected failure on GPIO {pin}: {exc}", file=sys.stderr)
        return False

    try:
        dev.value = state
    except GPIODeviceClosed:
        print(f"ERROR: GPIO {pin} device closed unexpectedly", file=sys.stderr)
        return False
    except Exception as exc:
        print(f"ERROR: failed to set GPIO {pin} to {state}: {exc}", file=sys.stderr)
        return False

    print(f"GPIO {pin} -> {'HIGH' if state else 'LOW'}")
    return True


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # --- Initialise outputs --------------------------------------------------
    for pin in OUTPUT_PINS:
        if not _set_output(pin, True):
            print("ERROR: one or more outputs could not be initialised.", file=sys.stderr)
            _cleanup()
            return 1

    # --- Main loop -----------------------------------------------------------
    try:
        while _running:
            for pin in OUTPUT_PINS:
                if not _set_output(pin, True):
                    break
            if not _running:
                break
            for pin in OUTPUT_PINS:
                if not _set_output(pin, False):
                    break
            if not _running:
                break

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < POLL_INTERVAL:
                time.sleep(0.2)
                slept += 0.2
    except Exception as exc:
        print(f"ERROR: unexpected exception in main loop: {exc}", file=sys.stderr)
        return 1
    finally:
        _cleanup()

    return 0


if __name__ == "__main__":
    sys.exit(main())

