import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# Digital output pins (BCM numbering)
OUTPUT_PINS = [0, 17]

# Sampling interval (seconds)
SAMPLE_INTERVAL = 0.5

# Global list so the signal handler can close it
outputs = []


def apply_output_states(states):
    """Apply a list of 0/1 values to the configured output pins.

    Returns True on success, False on hardware error.
    """
    for pin, state in zip(OUTPUT_PINS, states):
        try:
            outputs[pin].value = bool(state)
        except GPIOZeroError as exc:
            print(f"Error writing to GPIO {pin}: {exc}", file=sys.stderr)
            return False
    return True


def cleanup(signum=None, frame=None):
    """Close all output devices and exit."""
    for dev in outputs:
        try:
            dev.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    # Initialize output devices; exit on failure
    for pin in OUTPUT_PINS:
        try:
            dev = OutputDevice(pin)
            outputs.append(dev)
        except GPIOZeroError as exc:
            print(f"Failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
            cleanup()
            sys.exit(1)

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    print("Starting output control loop. Press Ctrl+C to stop.")

    try:
        while True:
            # Generate a sample: [0, 1]
            sample = [0, 1]

            if apply_output_states(sample):
                print(f"GPIO {OUTPUT_PINS[0]}={sample[0]}, "
                      f"GPIO {OUTPUT_PINS[1]}={sample[1]}")

            time.sleep(SAMPLE_INTERVAL)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

