import signal
import sys
import time

from gpiozero import LED
from gpiozero.exc import GPIOZeroError

# Digital outputs on GPIO 12 and GPIO 16 (BCM numbering)
OUTPUT_PINS = [12, 16]

# Graceful-shutdown flag
_running = True


def _handle_signal(signum, frame):
    """Signal handler for SIGINT / SIGTERM."""
    global _running
    _running = False


def main():
    global _running

    # Register signal handlers for clean exit on Ctrl-C / kill
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    outputs = []
    try:
        for pin in OUTPUT_PINS:
            try:
                outputs.append(LED(pin))
            except GPIOZeroError as exc:
                print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                return 1

        print("Starting output control loop (GPIO 12, 16). Press Ctrl-C to stop.")

        while _running:
            for idx, out in enumerate(outputs, start=1):
                try:
                    out.on()
                    state = "ON"
                except GPIOZeroError as exc:
                    print(f"Error: failed to set GPIO {OUTPUT_PINS[idx - 1]} to ON: {exc}", file=sys.stderr)
                    state = "ERROR"

            print(f"GPIO {OUTPUT_PINS[0]}={state}, GPIO {OUTPUT_PINS[1]}={state}")

            for idx, out in enumerate(outputs, start=1):
                try:
                    out.off()
                    state = "OFF"
                except GPIOZeroError as exc:
                    print(f"Error: failed to set GPIO {OUTPUT_PINS[idx - 1]} to OFF: {exc}", file=sys.stderr)
                    state = "ERROR"

            print(f"GPIO {OUTPUT_PINS[0]}={state}, GPIO {OUTPUT_PINS[1]}={state}")

            time.sleep(0.5)

    finally:
        # Release every output cleanly
        for out in outputs:
            try:
                out.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

