import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
I2C_ADDR = 0x76
READ_INTERVAL_S = 5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_bmp280(bus):
    """Read a raw measurement from the BMP280 and print it."""
    try:
        msg_w = i2c_msg.write(I2C_ADDR, [0xF4])
        msg_r = i2c_msg.read(I2C_ADDR, 80)
        bus.i2c_rdwr(msg_w, msg_r)
        data = list(msg_r)
        print(f"BMP280 reading: {data}")
    except OSError as exc:
        print(f"Error reading BMP280: {exc}", file=sys.stderr)
        raise


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Failed to open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                read_bmp280(bus)
            except OSError:
                pass
            for _ in range(READ_INTERVAL_S):
                if not _running:
                    break
                time.sleep(1)
    finally:
        bus.close()
        print("I2C bus closed. Exiting.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

import serial

PORT = "/dev/serial0"
BAUD = 115200
TIMEOUT = 1.0
POLL_INTERVAL = 0.1

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _read_once(ser):
    """Return a valid reading or None on error/timeout/invalid data."""
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        text = raw.decode("ascii", errors="replace").strip()
    except Exception as exc:
        print(f"Decode error: {exc}", file=sys.stderr)
        return None
    if not text:
        return None
    try:
        value = float(text)
    except ValueError:
        print(f"Invalid data (not a float): '{text}'", file=sys.stderr)
        return None
    if not (-100.0 <= value <= 100.0):
        print(f"Value out of range: {value}", file=sys.stderr)
        return None
    return value

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUD,
            timeout=TIMEOUT,
            write_timeout=TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Failed to open {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    print(f"Connected to {PORT} @ {BAUD} baud. Press Ctrl-C to stop.")

    try:
        while _running:
            reading = _read_once(ser)
            if reading is not None:
                print(f"Reading: {reading:.2f}")
            time.sleep(POLL_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Exited cleanly.")

if __name__ == "__main__":
    main()

