import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

INA219_ADDR = 0x40
INA219_REG_CONFIG = 0x00
INA219_REG_SHUNTVOLTAGE = 0x01
INA219_REG_BUSVOLTAGE = 0x02
INA219_REG_POWER = 0x03
INA219_REG_CURRENT = 0x04
INA219_REG_CALIBRATION = 0x05

CONFIG_16V_3200mA = 0x1000


class INA219:
    def __init__(self, bus_num=1, address=INA219_ADDR):
        self.address = address
        self.bus = SMBus(bus_num)
        self._running = True
        self._install_signal_handlers()
        self._configure()

    def _install_signal_handlers(self):
        for sig in (signal.SIGINT, signal.SIGTERM):
            signal.signal(sig, self._handle_signal)

    def _handle_signal(self, signum, frame):
        print(f"\nReceived signal {signum}, shutting down...")
        self._running = False

    def _configure(self):
        self.bus.write_word_data(self.address, INA219_REG_CONFIG, CONFIG_16V_3200mA)
        time.sleep(0.01)
        cfg = self.bus.read_word_data(self.address, INA219_REG_CONFIG)
        if cfg != CONFIG_16V_3200mA:
            raise RuntimeError(f"INA219 config failed: expected 0x{CONFIG_16V_3200mA:04X}, got 0x{cfg:04X}")

    def read_power(self):
        raw = self.bus.read_word_data(self.address, INA219_REG_POWER)
        if raw == 0xFFFF:
            raise RuntimeError("INA219 returned 0xFFFF (device absent or bus error)")
        return raw

    def close(self):
        try:
            self.bus.close()
        except Exception:
            pass


def main():
    ina = None
    try:
        ina = INA219(bus_num=1, address=INA219_ADDR)
        print("INA219 initialized at address 0x40")
        while ina._running:
            try:
                power = ina.read_power()
                print(f"Power: {power}")
            except RuntimeError as e:
                print(f"Read error: {e}", file=sys.stderr)
            time.sleep(2)
    except Exception as e:
        print(f"Initialization error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ina is not None:
            ina.close()


if __name__ == "__main__":
    main()

