import signal
import sys
import time

from gpiozero import LED
from gpiozero.exc import GPIOZeroError

# Digital outputs on GPIO 17 and GPIO 18 (BCM numbering)
OUTPUT_PINS = [17, 18]

# Global list so the signal handler can close it
outputs = []


def set_output(pin, state):
    """Set the given pin to `state` (True=high, False=low) and print the result."""
    try:
        led = LED(pin)
        led.on() if state else led.off()
        print(f"GPIO {pin} -> {'HIGH' if state else 'LOW'}")
    except GPIOZeroError as exc:
        print(f"Error setting GPIO {pin}: {exc}", file=sys.stderr)
    finally:
        led.close()


def cleanup(signum=None, frame=None):
    """Release all GPIO resources and exit."""
    for led in outputs:
        try:
            led.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        for pin in OUTPUT_PINS:
            led = LED(pin)
            outputs.append(led)

        while True:
            for pin in OUTPUT_PINS:
                set_output(pin, True)
            time.sleep(0.1)

            for pin in OUTPUT_PINS:
                set_output(pin, False)
            time.sleep(0.1)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

