import time

import w1thermsensor

# DS18B20 1-Wire bus on GPIO 4 (BCM)
# Wiring: DS18B20 VCC -> 3V3, GND -> GND, DATA -> GPIO 4

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
