import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, BadPinFactory

# HC-SR04 timing constants (seconds)
SOUND_SPEED = 343.0
MIN_DISTANCE = 2.0  # cm
MAX_DISTANCE = 400.0  # cm
TIMEOUT = 0.030  # 30 ms max wait for echo


def validate(distance: float) -> bool:
    """Return True if distance is within the HC-SR04 valid range."""
    return MIN_DISTANCE <= distance <= MAX_DISTANCE


def measure(sensor: DistanceSensor) -> float | None:
    """
    Attempt one distance measurement.
    Returns the distance in cm, or None if the reading is invalid or timed out.
    """
    deadline = time.monotonic() + TIMEOUT
    while time.monotonic() < deadline:
        try:
            dist = sensor.distance * 100.0  # gpiozero reports meters
        except GPIOZeroError:
            return None
        if validate(dist):
            return dist
    return None


def main() -> int:
    try:
        sensor = DistanceSensor(echo=17, trigger=18, max_distance=4.0)
    except BadPinFactory:
        print("ERROR: No GPIO pin factory available.", file=sys.stderr)
        return 1
    except GPIOZeroError as exc:
        print(f"ERROR: Failed to initialize HC-SR04: {exc}", file=sys.stderr)
        return 1

    try:
        for cycle in range(10):
            dist = measure(sensor)
            if dist is None:
                print(f"Cycle {cycle + 1}: NO_RESPONSE (timeout or out of range)")
            else:
                print(f"Cycle {cycle + 1}: {dist:.2f} cm")
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nInterrupted by user.", file=sys.stderr)
        return 130
    finally:
        sensor.close()

    return 0


if __name__ == "__main__":
    sys.exit(main())

