import time
import signal
import sys

from gpiozero import PCA9685


class PWMController:
    """
    Controls a PCA9685 PWM controller on a Raspberry Pi using gpiozero.

    The PCA9685 is a 16-channel, 12-bit PWM controller.  This class
    configures channel 0 and reports its current duty cycle every second.
    """

    def __init__(self, address=0x40, frequency=50):
        self.address = address
        self.frequency = frequency
        self.pwm = None
        self._running = True

        try:
            self.pwm = PCA9685(address=address, frequency=frequency)
        except Exception as exc:
            print(f"Error: Failed to initialize PCA9685 at 0x{address:02X}: {exc}", file=sys.stderr)
            sys.exit(1)

        # Configure channel 0: 16-bit range, 50 Hz, 0 % duty cycle
        self.pwm.channels[0].frequency = frequency
        self.pwm.channels[0].value = 0.0

    def read_channel(self, channel=0):
        """
        Read the current duty-cycle value of a PCA9685 channel.

        Returns a float in the range [0.0, 1.0].
        Raises RuntimeError on bus errors or invalid data.
        """
        if not 0 <= channel <= 15:
            raise ValueError(f"Invalid channel {channel}; must be 0-15")

        try:
            value = self.pwm.channels[channel].value
        except Exception as exc:
            raise RuntimeError(f"Failed to read channel {channel}: {exc}") from exc

        if not (0.0 <= value <= 1.0):
            raise RuntimeError(f"Invalid duty-cycle value on channel {channel}: {value}")

        return value

    def cleanup(self):
        """Release hardware resources held by the PCA9685."""
        if self.pwm is not None:
            try:
                self.pwm.close()
            except Exception:
                pass
            self.pwm = None

    def stop(self):
        """Signal the main loop to exit."""
        self._running = False


def main():
    controller = PWMController(address=0x40, frequency=50)

    def signal_handler(signum, frame):
        print("\nInterrupt received, exiting...")
        controller.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while controller._running:
            try:
                duty = controller.read_channel(0)
                print(f"Channel 0 duty cycle: {duty:.3f}")
            except RuntimeError as exc:
                print(f"Error reading channel 0: {exc}", file=sys.stderr)
                break

            time.sleep(1)
    finally:
        controller.cleanup()


if __name__ == "__main__":
    main()

