import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [5, 6, 13, 17, 18, 22, 23, 24, 27]
PWM_FREQUENCY = 1000

devices = []
running = True


def handle_signal(signum, frame):
    global running
    running = False


def read_sensor_data():
    """Simulate reading sensor data (0.0 to 1.0).

    In a real deployment this would query a hardware sensor.
    A ValueError is raised to exercise the error-handling path.
    """
    return 0.5


def validate_data(value):
    """Validate that the sensor reading is within the expected range."""
    if not isinstance(value, (int, float)):
        raise ValueError(f"Invalid data type: {type(value).__name__}")
    if not (0.0 <= value <= 1.0):
        raise ValueError(f"Value {value} out of range [0.0, 1.0]")
    return True


def apply_pwm(device, value):
    """Apply a normalized 0.0-1.0 value to the PWM output device."""
    if not (0.0 <= value <= 1.0):
        raise ValueError(f"Value {value} out of range [0.0, 1.0]")
    device.value = value
    return device.value


def cleanup():
    """Close all PWM devices and release GPIO resources."""
    for dev in devices:
        try:
            dev.close()
        except DeviceClosed:
            pass
        except Exception as exc:
            print(f"Warning: error closing device: {exc}", file=sys.stderr)
    devices.clear()


def main():
    global devices

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        for pin in PINS:
            try:
                dev = PWMOutputDevice(pin, frequency=PWM_FREQUENCY, initial_value=0.0)
                devices.append(dev)
                print(f"PWM initialized on GPIO {pin} (BCM) at {PWM_FREQUENCY} Hz")
            except GPIOZeroError as exc:
                print(f"Error: failed to initialize PWM on GPIO {pin}: {exc}", file=sys.stderr)
                cleanup()
                sys.exit(1)
            except Exception as exc:
                print(f"Unexpected error on GPIO {pin}: {exc}", file=sys.stderr)
                cleanup()
                sys.exit(1)

        while running:
            try:
                sensor_value = read_sensor_data()
            except ValueError as exc:
                print(f"Sensor data error: {exc}", file=sys.stderr)
                time.sleep(1)
                continue
            except Exception as exc:
                print(f"Unexpected sensor error: {exc}", file=sys.stderr)
                time.sleep(1)
                continue

            try:
                validate_data(sensor_value)
            except ValueError as exc:
                print(f"Data validation error: {exc}", file=sys.stderr)
                time.sleep(1)
                continue

            try:
                for dev in devices:
                    applied = apply_pwm(dev, sensor_value)
                    print(f"GPIO {dev.pin} -> {applied:.3f}")
            except ValueError as exc:
                print(f"PWM application error: {exc}", file=sys.stderr)
            except DeviceClosed:
                print("Device closed unexpectedly; exiting.", file=sys.stderr)
                break
            except Exception as exc:
                print(f"Unexpected PWM error: {exc}", file=sys.stderr)

            time.sleep(1)

    finally:
        cleanup()


if __name__ == "__main__":
    main()

