                    text = line.decode("utf-8", errors="replace").strip()
                    print(f"Reading {i + 1}/{READINGS}: {text}")
            except serial.SerialException as exc:
                print(f"Error reading from {PORT}: {exc}", file=sys.stderr)
                break
            if i < READINGS - 1 and _running:
                time.sleep(INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass

