import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, BadPinFactory

# HC-SR04 wiring (BCM numbering)
ECHO_PIN = 17
TRIGGER_PIN = 22

# HC-SR04 timing / range
TRIGGER_PULSE_S = 1e-5
SETTLE_S = 0.00005
MAX_DISTANCE_M = 4.0
SAMPLE_INTERVAL_S = 0.5


class HC04:
    """Thin wrapper around gpiozero.DistanceSensor for the HC-SR04."""

    def __init__(self, echo_pin, trigger_pin):
        try:
            self.sensor = DistanceSensor(
                echo=echo_pin,
                trigger=trigger_pin,
                max_distance=MAX_DISTANCE_M,
            )
        except BadPinFactory:
            raise RuntimeError("No GPIO pin factory available (not running on a Pi?)")
        except GPIOZeroError as exc:
            raise RuntimeError(f"Failed to initialise HC-SR04: {exc}")

    def measure(self):
        """Return distance in metres, or None if the sensor did not respond."""
        try:
            dist = self.sensor.distance
            if dist is None:
                return None
            if dist < 0 or dist > MAX_DISTANCE_M:
                return None
            return dist
        except GPIOZeroError:
            return None

    def close(self):
        try:
            self.sensor.close()
        except Exception:
            pass


def main():
    hc = None
    running = True

    def _shutdown(signum, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, _shutdown)
    signal.signal(signal.SIGTERM, _shutdown)

    try:
        hc = HC04(ECHO_PIN, TRIGGER_PIN)
    except RuntimeError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            dist = hc.measure()
            if dist is None:
                print("No echo received (sensor absent or out of range)")
            else:
                print(f"Distance: {dist:.3f} m")
            time.sleep(SAMPLE_INTERVAL_S)
    finally:
        if hc is not None:
            hc.close()


if __name__ == "__main__":
    main()

